package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.comparison.*;import com.aistock.prediction.marketuse.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class ComparisonUseMysqlTest {
 static class Setup {final ModelDatabaseFixture db=new ModelDatabaseFixture();final ComparisonMysqlTest samples=new ComparisonMysqlTest();final ComparisonRepository repo=new ComparisonRepository(db.jdbc,ComparisonTestEvidence.M);final UUID user=UUID.randomUUID();final List<JsonNode> sources=samples.sources();final ComparisonRecords.Input input=samples.input(sources);final AtomicReference<Instant> time=new AtomicReference<>(samples.now);final Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return time.get();}};final MarketUseClient client=mock(MarketUseClient.class);final ComparisonMarketUseOwner uses=new ComparisonMarketUseOwner(db.jdbc,ComparisonTestEvidence.M,repo,client,clock,true);Setup(){when(client.register(any())).thenAnswer(call->new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",new TreeSet<>(sources.stream().map(n->n.path("rawVersionId").asText()).toList()).stream().toList()));when(client.complete(any(),any())).thenAnswer(call->{var b=(MarketUseClient.Receipt)call.getArgument(1);return new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());});}}
 @Test void proofRetiresExpiredExecutionButPreservesReclaimAndRejectsClockRollbackWrite(){var s=new Setup();var a=s.repo.claim(s.user,s.input,s.time.get());try(var scope=s.uses.acquire(s.user,s.input,a.generation())){}assertThrows(com.aistock.common.BusinessException.class,()->s.uses.proof(a.generation(),"1"));s.time.set(s.samples.now.plusSeconds(46));var old=s.uses.proof(a.generation(),"1");assertEquals("FAILED",old.path("state").asText());assertTrue(s.repo.operation(s.user,s.input.requestId(),s.time.get()).expired());var calc=new ComparisonCalculator(s.clock).calculate(s.input,s.sources);assertThrows(RuntimeException.class,()->s.repo.complete(s.user,s.input,a.generation(),calc,s.sources,s.samples.now.plusSeconds(1)));var b=s.repo.claim(s.user,s.input,s.time.get());assertTrue(b.execute());assertNotEquals(a.generation(),b.generation());try(var scope=s.uses.acquire(s.user,s.input,b.generation())){}var done=s.repo.complete(s.user,s.input,b.generation(),calc,s.sources,s.time.get().plusSeconds(1));assertEquals("SUCCEEDED",done.state());assertEquals(old,s.uses.proof(a.generation(),"1"));assertEquals("SUCCEEDED",s.uses.proof(b.generation(),"1").path("state").asText());assertThrows(com.aistock.common.BusinessException.class,()->s.uses.proof(b.generation(),"2"));}
 @Test void reclaimBeforeProofKeepsOldAttemptTerminalAndUsesNewRegistration(){var s=new Setup();var a=s.repo.claim(s.user,s.input,s.time.get());try(var scope=s.uses.acquire(s.user,s.input,a.generation())){}s.time.set(s.samples.now.plusSeconds(46));var b=s.repo.claim(s.user,s.input,s.time.get());try(var scope=s.uses.acquire(s.user,s.input,b.generation())){assertEquals(b.generation().toString(),MarketUseContext.headers().get("X-Market-Use-Operation"));}assertEquals("FAILED",s.uses.proof(a.generation(),"1").path("state").asText());var captured=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);verify(s.client,times(2)).register(captured.capture());assertNotEquals(captured.getAllValues().get(0).requestId(),captured.getAllValues().get(1).requestId());for(var r:captured.getAllValues()){assertEquals("COMPARISON_EVIDENCE",r.selector().kind());assertEquals(2,r.selector().evidence().size());}assertFalse(s.repo.operation(s.user,s.input.requestId(),s.time.get()).expired());}
 @Test void concurrentReclaimAndProofCannotRetireNewExecution()throws Exception{var s=new Setup();var a=s.repo.claim(s.user,s.input,s.time.get());try(var scope=s.uses.acquire(s.user,s.input,a.generation())){}s.time.set(s.samples.now.plusSeconds(46));var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var claim=pool.submit(()->{barrier.await(5,TimeUnit.SECONDS);return s.repo.claim(s.user,s.input,s.time.get());});var proof=pool.submit(()->{barrier.await(5,TimeUnit.SECONDS);return s.uses.proof(a.generation(),"1");});var b=claim.get(5,TimeUnit.SECONDS);assertEquals("FAILED",proof.get(5,TimeUnit.SECONDS).path("state").asText());assertEquals(b.generation().toString(),s.db.jdbc.queryForObject("select lease_generation from stock_comparison_operation where owner_id=? and request_id=?",String.class,s.user.toString(),s.input.requestId().toString()));assertFalse(s.repo.operation(s.user,s.input.requestId(),s.time.get()).expired());}finally{pool.shutdownNow();}}

 @Test void actualComparisonKeepsOldEvidenceAndNotifiesAfterImmutableCommit(){var s=new Setup();var market=mock(ComparisonMarketClient.class);when(market.evidence(any())).thenAnswer(call->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());assertEquals("COMPARISON",MarketUseContext.headers().get("X-Market-Use-Purpose"));assertEquals(2,MarketUseContext.expectedVersions().size());return s.sources.get(s.input.evidenceIds().indexOf(call.getArgument(0)));});doAnswer(call->{assertTrue(MarketUseContext.headers().isEmpty());assertEquals(1,s.db.jdbc.queryForObject("select count(*) from stock_comparison_result",Integer.class));var b=(MarketUseClient.Receipt)call.getArgument(1);return new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds());}).when(s.client).complete(any(),any());var svc=new ComparisonService(s.repo,market,ComparisonTestEvidence.M,s.clock,2,s.uses);var result=svc.create(s.user,s.input).operation();assertEquals("SUCCEEDED",result.state());var saved=s.repo.get(s.user,result.comparisonId()).toString();var execution=UUID.fromString(s.db.jdbc.queryForObject("select execution_id from comparison_market_use",String.class));assertEquals(result.comparisonId().toString(),s.uses.proof(execution,"1").path("resultIdentity").asText());assertEquals(result,svc.create(s.user,s.input).operation());assertEquals(saved,s.repo.get(s.user,result.comparisonId()).toString());verify(market,times(2)).evidence(any());verify(market,never()).options(anyList(),anyString());verify(s.client,times(1)).register(any());assertTrue(s.db.jdbc.queryForObject("select completion_acked from comparison_market_use",Boolean.class));}
 @Test void deniedComparisonNeverReadsEvidenceAndWrongManifestNeverSavesResult(){for(boolean denied:List.of(true,false)){var s=new Setup();var market=mock(ComparisonMarketClient.class);when(market.evidence(any())).thenAnswer(call->s.sources.get(s.input.evidenceIds().indexOf(call.getArgument(0))));if(denied)doThrow(MarketUseClient.notReady()).when(s.client).requireReady();else doReturn(new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString(),UUID.randomUUID().toString()))).when(s.client).register(any());var svc=new ComparisonService(s.repo,market,ComparisonTestEvidence.M,s.clock,2,s.uses);assertThrows(com.aistock.common.BusinessException.class,()->svc.create(s.user,s.input));assertEquals("FAILED",s.repo.operation(s.user,s.input.requestId(),s.time.get()).state());assertEquals(0,s.db.jdbc.queryForObject("select count(*) from stock_comparison_result",Integer.class));if(denied)verify(market,never()).evidence(any());assertTrue(MarketUseContext.headers().isEmpty());}}
 @Test void unknownComparisonRegistrationRecoversWithoutAnotherPostOrSourceRead(){var s=new Setup();doThrow(MarketUseClient.unavailable()).when(s.client).register(any());var market=mock(ComparisonMarketClient.class);var svc=new ComparisonService(s.repo,market,ComparisonTestEvidence.M,s.clock,2,s.uses);assertThrows(com.aistock.common.BusinessException.class,()->svc.create(s.user,s.input));var captured=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);verify(s.client).register(captured.capture());var request=captured.getValue();var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",new TreeSet<>(s.sources.stream().map(n->n.path("rawVersionId").asText()).toList()).stream().toList());when(s.client.find(request)).thenReturn(Optional.of(b));var restarted=new ComparisonMarketUseOwner(s.db.jdbc,ComparisonTestEvidence.M,s.repo,s.client,s.clock,true);restarted.recoverOne(UUID.fromString(request.operationId()));verify(s.client,times(1)).register(any());verify(s.client).find(request);verifyNoInteractions(market);assertTrue(s.db.jdbc.queryForObject("select completion_acked from comparison_market_use",Boolean.class));assertEquals("FAILED",restarted.proof(UUID.fromString(request.operationId()),"1").path("state").asText());}
}
